"use client";
import { useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { reasonCodes, type MutationResult } from "@/lib/admin/contracts";
export function ReasonSelect() {
  return (
    <label className="block">
      Reason
      <select
        name="reasonCode"
        required
        className="mt-1 block min-h-11 rounded-sm border bg-surface px-3"
      >
        {reasonCodes.map((r) => (
          <option key={r}>{r}</option>
        ))}
      </select>
    </label>
  );
}
const messages = {
  DENIED: "Access denied. Refresh your session.",
  REAUTH_REQUIRED:
    "Verify your Google identity above before changing settings.",
  INVALID_INPUT: "Check dates, confirmation, and selected values.",
  CONFLICT:
    "The request conflicts with a previous operation. Refresh before trying again.",
  RATE_LIMITED: "Mutation limit reached. Try again in one minute.",
  UNAVAILABLE: "The change could not be completed. Retry with the same values.",
};
export function MutationForm({
  children,
  submit,
}: {
  children: React.ReactNode;
  submit: (data: FormData, requestId: string) => Promise<MutationResult>;
}) {
  const requestId = useRef<string | null>(null),
    [pending, start] = useTransition(),
    [message, setMessage] = useState(""),
    router = useRouter();
  return (
    <form
      onChange={() => {
        requestId.current = null;
        setMessage("");
      }}
      onSubmit={(event) => {
        event.preventDefault();
        const form = event.currentTarget;
        const data = new FormData(form);
        start(async () => {
          requestId.current ??= crypto.randomUUID();
          try {
            const result = await submit(data, requestId.current);
            setMessage(result.ok ? "Change saved." : messages[result.code]);
            if (result.ok) {
              requestId.current = null;
              for (const checkbox of form.querySelectorAll<HTMLInputElement>(
                'input[type="checkbox"]',
              ))
                checkbox.checked = false;
              router.refresh();
            }
          } catch {
            setMessage(messages.UNAVAILABLE);
          }
        });
      }}
    >
      <fieldset disabled={pending} className="space-y-4">
        {children}
      </fieldset>
      <p role="status" aria-live="polite" className="mt-3">
        {pending ? "Saving…" : message}
      </p>
    </form>
  );
}
